begin;

create temporary table tmp_beautydna_core_150 (
  priority_rank integer,
  coverage_tier text,
  canonical_inci_name text,
  normalized_ingredient_name text,
  ingredient_slug text,
  preferred_display_name_en text,
  japanese_labeling_name text,
  ingredient_family text,
  primary_function_summary text,
  common_product_types text[]
) on commit drop;


-- Update any existing matching records first.
update public.beautydna_ingredient_intelligence i
set
  canonical_inci_name = s.canonical_inci_name,
  normalized_ingredient_name = s.normalized_ingredient_name,
  ingredient_slug = coalesce(i.ingredient_slug, s.ingredient_slug),
  preferred_display_name_en = coalesce(i.preferred_display_name_en, s.preferred_display_name_en),
  preferred_display_name_ja = coalesce(i.preferred_display_name_ja, s.japanese_labeling_name),
  japanese_labeling_name = coalesce(i.japanese_labeling_name, s.japanese_labeling_name),
  ingredient_family = coalesce(i.ingredient_family, s.ingredient_family),
  primary_function_summary = coalesce(i.primary_function_summary, s.primary_function_summary),
  common_product_types = case
    when coalesce(cardinality(i.common_product_types), 0) = 0 then s.common_product_types
    else i.common_product_types
  end,
  research_priority = s.priority_rank,
  coverage_tier = s.coverage_tier,
  schema_version = 'beauty-intelligence-ingredient-v1',
  record_status = coalesce(i.record_status, 'active'),
  review_status = coalesce(i.review_status, 'needs_review'),
  customer_usable = case when i.review_status = 'approved' then i.customer_usable else false end,
  updated_at = now()
from tmp_beautydna_core_150 s
where i.normalized_ingredient_name = s.normalized_ingredient_name
   or lower(i.canonical_inci_name) = lower(s.canonical_inci_name);

-- Insert only records that do not exist.
  canonical_inci_name,
  normalized_ingredient_name,
  ingredient_slug,
  preferred_display_name_en,
  preferred_display_name_ja,
  japanese_labeling_name,
  ingredient_family,
  primary_function_summary,
  common_product_types,
  research_priority,
  coverage_tier,
  schema_version,
  record_status,
  review_status,
  customer_usable,
  current_version,
  created_at,
  updated_at
)
select
  s.canonical_inci_name,
  s.normalized_ingredient_name,
  s.ingredient_slug,
  s.preferred_display_name_en,
  s.japanese_labeling_name,
  s.japanese_labeling_name,
  s.ingredient_family,
  s.primary_function_summary,
  s.common_product_types,
  s.priority_rank,
  s.coverage_tier,
  'beauty-intelligence-ingredient-v1',
  'active',
  'needs_review',
  false,
  1,
  now(),
  now()
from tmp_beautydna_core_150 s
where not exists (
  select 1
  from public.beautydna_ingredient_intelligence i
  where i.normalized_ingredient_name = s.normalized_ingredient_name
     or lower(i.canonical_inci_name) = lower(s.canonical_inci_name)
);

create temporary table tmp_beautydna_aliases (
  ingredient_normalized_name text,
  alias_name text,
  normalized_alias_name text,
  language_code text,
  alias_type text,
  is_official boolean,
  is_ambiguous boolean,
  refers_to_scope text
) on commit drop;


  ingredient_id,
  alias_name,
  normalized_alias_name,
  language_code,
  alias_type,
  is_official,
  is_ambiguous,
  refers_to_scope,
  review_status,
  created_at,
  updated_at
)
select
  i.id,
  a.alias_name,
  a.normalized_alias_name,
  a.language_code,
  a.alias_type,
  a.is_official,
  a.is_ambiguous,
  a.refers_to_scope,
  'needs_review',
  now(),
  now()
from tmp_beautydna_aliases a
join public.beautydna_ingredient_intelligence i
  on i.normalized_ingredient_name = a.ingredient_normalized_name
where not exists (
  select 1
  from public.beautydna_ingredient_aliases e
  where e.ingredient_id = i.id
    and lower(e.alias_name) = lower(a.alias_name)
);

commit;
